#include <stdio.h>



int main(void) {
    double x, sum = 0, high = 0, low = 100;
    for (int i = 0; i < 10; i++) {
        scanf("%lf", &x); sum += x;
        if (x > high) high = x;
        if (x < low) low = x;
    }
    printf("%.2f %.2f %.2f\n", sum / 10, high, low);
    return 0;
}
